.title {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
  margin: 0 0 3px;
}

.subtitle {
  font-size: var(--bw-size-body);
  line-height: 1.6;
  color: var(--bw-text-secondary);
  margin: 0 0 16px;
  max-width: 640px;
}

.feedback {
  font-size: 13px;
  line-height: 1.5;
  color: var(--bw-success-dark);
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  padding: 8px 11px;
  margin: 0 0 16px;
  max-width: 640px;
}

.loadError {
  font-size: 13px;
  line-height: 1.5;
  color: var(--bw-error-text);
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  padding: 8px 11px;
  margin: 0 0 16px;
}

.chips {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.chip {
  height: 28px;
  padding: 0 14px;
  border-radius: 14px;
  border: 1px solid var(--bw-line-steel-strong);
  /* No hay token de superficie blanca pura; --bw-surface-mist es el blanco más cercano. */
  background: var(--bw-surface-mist);
  font-family: var(--bw-font-body);
  font-size: 12px;
  font-weight: 500;
  color: var(--bw-text-secondary);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.chip:hover:not(.chipActive) {
  border-color: var(--bw-hover-border);
  color: var(--bw-ink-steel);
}

.chipActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-on-dark-hover);
}

.chipCount {
  font-size: 10px;
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 8px;
  background: var(--bw-cold-white);
  color: var(--bw-text-secondary);
}

.chipActive .chipCount {
  background: var(--bw-on-dark-fill-4);
  color: var(--bw-on-dark-hover);
}

.deletionSection {
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-badge-danger-border);
  border-left: 3px solid var(--bw-danger);
  border-radius: 6px;
  padding: 12px 16px;
  margin-bottom: 16px;
}

.deletionTitle {
  font-size: 12px;
  font-weight: 600;
  color: var(--bw-danger);
  margin: 0 0 8px;
}

.candidateRow {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 7px 0;
  border-bottom: 0.5px solid var(--bw-divider-mist);
  font-size: 12px;
  color: var(--bw-ink-steel);
}

.candidateRow:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.candidateName {
  font-weight: 500;
  flex: 1;
  min-width: 180px;
}

.candidateCountry {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  font-weight: 500;
  color: var(--bw-ink-steel);
}

.candidateMeta {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  color: var(--bw-input-placeholder);
}

.deleteButton {
  height: 26px;
  padding: 0 12px;
  background: none;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  color: var(--bw-danger);
  font-family: var(--bw-font-body);
  font-size: 11px;
  font-weight: 500;
  cursor: not-allowed;
  white-space: nowrap;
}

