.panel {
  /* El panel no conoce el ancho de VERA del shell: fijo a la derecha, por
     encima del contenido. No hay token de sombra; --bw-sidebar-overlay es el
     único negro translúcido del sistema. */
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 360px;
  max-width: calc(100vw - 32px);
  background: var(--bw-surface-mist);
  border-left: 1px solid var(--bw-line-steel);
  box-shadow: -6px 0 18px var(--bw-sidebar-overlay);
  z-index: 40;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.header {
  padding: 14px 16px;
  border-bottom: 1px solid var(--bw-divider-mist);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-shrink: 0;
  background: var(--bw-surface-mist);
}

.eyebrow {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bw-brass);
  margin: 0 0 3px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 13px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  line-height: 1.3;
  margin: 0;
}

.closeButton {
  width: 28px;
  height: 28px;
  background: none;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bw-input-placeholder);
  font-size: 18px;
  border-radius: var(--bw-radius);
  flex-shrink: 0;
  margin-left: 8px;
  font-family: var(--bw-font-body);
}

