  background: var(--bw-cold-white);
  color: var(--bw-deep-steel);
}

.body {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}

.dataList {
  margin: 0 0 16px;
}

.dt {
  font-size: 11px;
  color: var(--bw-input-placeholder);
  margin: 0;
  padding: 0;
}

.dd {
  font-size: 12px;
  color: var(--bw-ink-steel);
  font-weight: 500;
  margin: 0 0 7px;
  padding: 0;
  word-break: break-all;
}

.section {
  margin-bottom: 16px;
}

.sectionTitle {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--bw-input-placeholder);
  margin: 0 0 8px;
}

.list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.listItem {
  padding: 7px 0;
  border-bottom: 0.5px solid var(--bw-divider-mist);
  font-size: 11px;
  line-height: 1.5;
  color: var(--bw-text-secondary);
}

.listItem:last-child {
  border-bottom: none;
